EXPECTED_SHA256 = "b60ef711d7883890faaf3e1eb55ff428c9e5775cd9fb5e84358684606a9ce1f7"
MAX_DIM = 1024
MAX_BYTES = 1024 * 1024


def check_png_header(data):
    """Validate the PNG signature and IHDR dimensions (<=1024x1024)."""
    if data[:8] != b"\x89PNG\r\n\x1a\n":
        return "not a PNG file"
    if len(data) < 33 or data[12:16] != b"IHDR":
        return "missing IHDR chunk"
    width, height = struct.unpack(">II", data[16:24])
    if width > MAX_DIM or height > MAX_DIM:
        return f"dimensions {width}x{height} exceed {MAX_DIM}x{MAX_DIM}"
    return None


def main():
    data = base64.b64decode("".join(PNG_B64))
    if len(data) > MAX_BYTES:
        print(f"self-check FAILED: {len(data)} bytes exceed 1 MiB", file=sys.stderr)
        return 1
    header_error = check_png_header(data)
    if header_error:
        print(f"self-check FAILED: {header_error}", file=sys.stderr)
        return 1
    os.makedirs("/output", exist_ok=True)
    out_path = "/output/entry.png"
    with open(out_path, "wb") as f:
        f.write(data)
    with open(out_path, "rb") as f:
        written = f.read()
    if written != data:
        print("self-check FAILED: written bytes differ from embedded bytes",
              file=sys.stderr)
        return 1
    digest = hashlib.sha256(written).hexdigest()
    if digest != EXPECTED_SHA256:
        print(f"self-check FAILED: sha256 {digest} != {EXPECTED_SHA256}",
              file=sys.stderr)
        return 1
    print(f"wrote {out_path} ({len(written)} bytes, sha256 {digest})")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
